import { Conversations } from "@godxjp/ui/navigation";

const [active, setActive] = useState("c1");

<Conversations
  activeKey={active}
  onActiveChange={setActive}
  groupable={{ collapsible: true }}
  creation={{ onClick: () => startNewChat() }}
  items={[
    { key: "c1", label: "請求書の下書き", group: "today" },
    { key: "c2", label: "経費精算の規則", group: "today" },
    { key: "c3", label: "出張手当の確認", group: "earlier" },
  ]}
  menu={{
    items: [
      { key: "rename", label: "名前を変更" },
      { key: "delete", label: "削除", danger: true },
    ],
    onClick: ({ key, conversation }) => run(key, conversation.key),
  }}
/>
